-- ===================================================================
-- TO-BE DB 재구성(2026-09): 물리 2개(gift + 나머지), 논리 6개 스키마 구조로 전환.
-- 이 파일은 이제 자신의 단독 DB가 아니라 'ghlove_core' DB 안의 'admin' 스키마에 적용한다.
-- 실행예: psql -U postgres -d ghlove_core -f service-admin.sql
-- ===================================================================
CREATE SCHEMA IF NOT EXISTS admin;
SET search_path TO admin;

-- Service: admin
-- ===================================================================
-- AS-IS 운영 DB 원본 스키마 기준 자동 생성 (159개 테이블)
-- 출처: 운영사이트 DB dump(CUBRID) -> PostgreSQL 변환. 인덱스는 이번 생성에서 제외(추후 실사용 쿼리 패턴 기반으로 추가).
-- 서비스간 FK는 제거됨(no cross-service FK 원칙).
-- ===================================================================

-- 기부자_주소지_기준_모금_순위_TOP_10
CREATE TABLE IF NOT EXISTS B_CNTR_ADDR (
    -- 년월일
    CNTR_YMD                     VARCHAR(8) NOT NULL,
    -- 기부지자체광역지역코드
    UPPER_LOCGOV_CODE            VARCHAR(10) NOT NULL,
    -- 기부지자체광역지역명
    UPPER_LOCGOV_NM              VARCHAR(50) NOT NULL,
    -- 기부지자체코드
    LOCGOV_CODE                  VARCHAR(10) NOT NULL,
    -- 기부지자체명
    LOCGOV_NM                    VARCHAR(50) NOT NULL,
    -- 기부자 주소지 코드
    CNTR_LOCGOV                  VARCHAR(10),
    -- 모금액
    CNTR_AMT                     BIGINT NOT NULL DEFAULT 0,
    -- 비중
    CNTR_RATE                    VARCHAR(10),
    -- 최초등록일시
    FRST_REG_DT                  TIMESTAMP NOT NULL DEFAULT now()
);

-- 기부금액_기부건수(전년비)
CREATE TABLE IF NOT EXISTS B_CNTR_AMT (
    -- 년월일
    CNTR_YMD                     VARCHAR(8) NOT NULL,
    -- 기부지자체광역지역코드
    UPPER_LOCGOV_CODE            VARCHAR(10) NOT NULL,
    -- 기부지자체광역지역명
    UPPER_LOCGOV_NM              VARCHAR(50) NOT NULL,
    -- 기부지자체코드
    LOCGOV_CODE                  VARCHAR(10) NOT NULL,
    -- 기부지자체명
    LOCGOV_NM                    VARCHAR(50) NOT NULL,
    -- 기부금액
    CNTR_AMT                     BIGINT NOT NULL DEFAULT 0,
    -- 전년도기부금액
    PRE_AMT                      BIGINT NOT NULL DEFAULT 0,
    -- 기부횟수
    CNTR_CNT                     BIGINT NOT NULL DEFAULT 0,
    -- 전년도기부횟수
    PRE_CNT                      BIGINT NOT NULL DEFAULT 0,
    -- 금액증감률
    AMT_RATE                     VARCHAR(10),
    -- 횟수증감률
    CNT_RATE                     VARCHAR(10),
    -- 최초등록일시
    FRST_REG_DT                  TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY (CNTR_YMD, LOCGOV_CODE)
);

-- 대상별_기부금액
CREATE TABLE IF NOT EXISTS B_CNTR_AMT_BIZ (
    -- 년월일
