    -- 기부지자체코드
    LOCGOV_CODE                  VARCHAR(10) NOT NULL,
    -- 기부지자체명
    LOCGOV_NM                    VARCHAR(50) NOT NULL,
    -- 자치단체금액
    CNTR_AMT                     BIGINT NOT NULL DEFAULT 0,
    -- 특정사업비율
    BIZ_AMT                      BIGINT NOT NULL DEFAULT 0,
    -- 자치단체비율
    CNTR_RATE                    VARCHAR(10),
    -- 특정사업비율
    BIZ_RATE                     VARCHAR(10),
    -- 최초등록일시
    FRST_REG_DT                  TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY (CNTR_YMD, LOCGOV_CODE)
);

-- 기부_금액별_건수
CREATE TABLE IF NOT EXISTS B_CNTR_AMT_CAT (
