-- 전년대비_월별_기부금액
CREATE TABLE IF NOT EXISTS B_CNTR_AMT_MM (
    -- 년도
    CNTR_YY                      VARCHAR(4) NOT NULL,
    -- 월
    CNTR_MM                      VARCHAR(2) NOT NULL,
    -- 기부지자체광역지역코드
