-- 커뮤니티 게시판
CREATE TABLE IF NOT EXISTS G_CMNTY_BBS (
    -- 게시판아이디
    BBS_ID                       BIGINT NOT NULL,
    -- 게시판제목
    BBS_TTL                      VARCHAR(300) NOT NULL,
    -- 게시판내용
    BBS_CN                       VARCHAR NOT NULL,
    -- 사용여부
    USE_YN                       VARCHAR(1) NOT NULL DEFAULT 'Y',
    -- 공지여부
    NOTICE_YN                    VARCHAR(1) DEFAULT 'N',
    -- 조회수
    INQ_CNT                      BIGINT DEFAULT 0,
    -- 최초등록아이디
    FRST_CRT_ID                  BIGINT NOT NULL,
    -- 최초등록일시
    FRST_CRT_DT                  TIMESTAMP NOT NULL DEFAULT now(),
    -- 최종수정아이디
    LAST_MDFCN_ID                BIGINT,
    -- 최종수정일시
    LAST_MDFCN_DT                TIMESTAMP,
    -- 비밀여부
    IS_SECRET                    VARCHAR(1) DEFAULT 'N',
    PRIMARY KEY (BBS_ID)
);
CREATE SEQUENCE IF NOT EXISTS g_cmnty_bbs_bbs_id_seq START WITH 1000;
ALTER TABLE G_CMNTY_BBS ALTER COLUMN BBS_ID SET DEFAULT nextval('g_cmnty_bbs_bbs_id_seq');
ALTER SEQUENCE g_cmnty_bbs_bbs_id_seq OWNED BY G_CMNTY_BBS.BBS_ID;

