-- 임시 암호화 데이터(유효시간 1분)
CREATE TABLE IF NOT EXISTS G_TEMP_ENC_DATA (
    -- 데이터 키
    DATA_ID                      VARCHAR(50) NOT NULL,
    -- 암호화 데이터
    ENC_DATA                     VARCHAR NOT NULL,
    -- 등록 일시
    REG_DT                       TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY (DATA_ID)
);

-- 복호화 키 생성 정보
CREATE TABLE IF NOT EXISTS G_TEMP_PRIVATE_KEY (
    -- 암복호화키 생성 user id
    USER_ID                      BIGINT NOT NULL,
    -- 복호화 키
    PRIVATE_KEY                  VARCHAR(5000) NOT NULL,
    -- 생성일
    CREATED_DATE                 TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY (USER_ID)
);

-- 답례품 주문내역 알림톡
CREATE TABLE IF NOT EXISTS NURI2_NRMSG_DATA (
    MSG_KEY                      NUMERIC(11,0) NOT NULL,
    SUB_ID                       VARCHAR(30),
    USER_KEY                     NUMERIC(11,0),
    USER_GROUP                   VARCHAR(30),
    USER_ID                      VARCHAR(30),
    USER_JOBID                   VARCHAR(40),
    CENTER_KEY                   NUMERIC(2,0) NOT NULL DEFAULT 1,
    MSG_PRIORITY                 NUMERIC(2,0) NOT NULL DEFAULT 3,
    MSG_STATE                    NUMERIC(2,0) NOT NULL DEFAULT 1,
    INPUT_DATE                   TIMESTAMP NOT NULL DEFAULT now(),
    RES_DATE                     TIMESTAMP NOT NULL DEFAULT now(),
    QUE_DATE                     TIMESTAMP,
    SENT_DATE                    TIMESTAMP,
    RSLT_DATE                    TIMESTAMP,
    REPORT_DATE                  TIMESTAMP,
    RSLT_CODE                    VARCHAR(4),
    RSLT_NET                     VARCHAR(3),
    RSLT_TYPE                    VARCHAR(3),
    SENT_COUNT                   NUMERIC(2,0) NOT NULL DEFAULT 0,
    HISTORY_MSG_TYPE             VARCHAR(23),
    HISTORY_RSLT_CODE            VARCHAR(28),
    IDENTIFIER                   VARCHAR(9),
    PHONE                        VARCHAR(20) NOT NULL,
    CALLBACK                     VARCHAR(20) NOT NULL,
    MSG_TYPE_1                   VARCHAR(3) NOT NULL DEFAULT 'SMS',
    CONTENTS_TYPE_1              VARCHAR(3) NOT NULL DEFAULT 'SMS',
    QUE_DATE_1                   TIMESTAMP,
    SENT_DATE_1                  TIMESTAMP,
    MSG_TYPE_2                   VARCHAR(3),
    CONTENTS_TYPE_2              VARCHAR(3),
    QUE_DATE_2                   TIMESTAMP,
    SENT_DATE_2                  TIMESTAMP,
    MSG_TYPE_3                   VARCHAR(3),
    CONTENTS_TYPE_3              VARCHAR(3),
    QUE_DATE_3                   TIMESTAMP,
    SENT_DATE_3                  TIMESTAMP,
    XMS_RSLT_CODE                VARCHAR(4),
    XMS_RSLT_NET                 VARCHAR(3),
    XMS_RSLT_DATE                TIMESTAMP,
    XMS_REPORT_DATE              TIMESTAMP,
    ALT_RSLT_CODE                VARCHAR(4),
    ALT_RSLT_NET                 VARCHAR(3),
    ALT_RSLT_DATE                TIMESTAMP,
    ALT_REPORT_DATE              TIMESTAMP,
    RCS_RSLT_CODE                VARCHAR(4),
    RCS_RSLT_NET                 VARCHAR(3),
    RCS_RSLT_DATE                TIMESTAMP,
    RCS_REPORT_DATE              TIMESTAMP,
    XMS_SUBJECT                  VARCHAR(60),
    XMS_TEXT                     VARCHAR(4000),
    XMS_FILE_NAME_1              VARCHAR(255),
    XMS_FILE_NAME_2              VARCHAR(255),
    XMS_FILE_NAME_3              VARCHAR(255),
    ALT_COUNTRY_CODE             VARCHAR(5) NOT NULL DEFAULT '82',
    ALT_SENDER_KEY               VARCHAR(40),
    ALT_TEMPLATE_CODE            VARCHAR(30),
    ALT_JSON                     VARCHAR(4000),
    RCS_BRAND_KEY                VARCHAR(18),
    RCS_BRAND_ID                 VARCHAR(100),
    RCS_MESSAGE_BASE_ID          VARCHAR(100),
    RCS_JSON                     VARCHAR(4000),
    PRIMARY KEY (MSG_KEY)
);
CREATE SEQUENCE IF NOT EXISTS nuri2_nrmsg_data_msg_key_seq START WITH 1000;
ALTER TABLE NURI2_NRMSG_DATA ALTER COLUMN MSG_KEY SET DEFAULT nextval('nuri2_nrmsg_data_msg_key_seq');
ALTER SEQUENCE nuri2_nrmsg_data_msg_key_seq OWNED BY NURI2_NRMSG_DATA.MSG_KEY;

