-- 알림톡 결과코드
CREATE TABLE IF NOT EXISTS NURI2_NRMSG_RSLT (
    -- 결과KEY
    RSLT_KEY                     NUMERIC(11,0) NOT NULL,
    -- 결과코드
    RSLT_CODE                    VARCHAR(4) NOT NULL,
    -- 결과유형
    RSLT_TYPE                    VARCHAR(3),
    -- 결과설명
    RSLT_EXPLA                   VARCHAR(200),
    PRIMARY KEY (RSLT_KEY)
);

-- 상점 계좌 정보
CREATE TABLE IF NOT EXISTS OP_ACCOUNT_NUMBER (
    -- 상점 환경설정 ID
    SHOP_CONFIG_ID               INTEGER NOT NULL DEFAULT 0,
    -- 상점 계좌 정보 ID
    ACCOUNT_NUMBER_ID            INTEGER NOT NULL DEFAULT 0,
    -- 은행명
    BANK_NAME                    VARCHAR(30),
    -- 계좌번호
    ACCOUNT_NUMBER               VARCHAR(210),
    -- 상점명
    ACCOUNT_HOLDER               VARCHAR(210),
    -- 사용여부
    USE_FLAG                     VARCHAR(1) DEFAULT 'Y',
    -- 회원ID
    USER_ID                      BIGINT NOT NULL DEFAULT 0,
    -- 등록일
    CREATED                      VARCHAR(14),
    PRIMARY KEY (ACCOUNT_NUMBER_ID, SHOP_CONFIG_ID)
);

CREATE TABLE IF NOT EXISTS OP_ALIM_TALK_TEMPLATE (
    ID                           BIGINT NOT NULL,
    CREATED                      TIMESTAMP,
    CREATED_BY                   BIGINT,
    UPDATED                      TIMESTAMP,
    UPDATED_BY                   BIGINT,
    APPLY_CODE                   VARCHAR(7) NOT NULL,
    CONTENT                      VARCHAR(1000) NOT NULL,
    EMPHASIZE_TYPE               VARCHAR(4) NOT NULL,
    INSP_STATUS                  VARCHAR(3) NOT NULL,
    MESSAGE_TYPE                 VARCHAR(2) NOT NULL,
    STATUS                       VARCHAR(1) NOT NULL,
    TEMPLATE_CODE                VARCHAR(40) NOT NULL,
    TITLE                        VARCHAR(20) NOT NULL,
    PRIMARY KEY (ID)
);

CREATE TABLE IF NOT EXISTS OP_ALIM_TALK_TEMPLATE_BUTTION (
    ID                           BIGINT NOT NULL,
    CREATED                      TIMESTAMP,
    CREATED_BY                   BIGINT,
    UPDATED                      TIMESTAMP,
    UPDATED_BY                   BIGINT,
    LINK_MOBILE                  VARCHAR(200),
    LINK_PC                      VARCHAR(200),
    NAME                         VARCHAR(28),
    ORDERING                     INTEGER,
    SCHEME_ANDROID               VARCHAR(200),
    SCHEME_IOS                   VARCHAR(200),
    TYPE                         VARCHAR(3),
    TYPE_NAME                    VARCHAR(10),
    ALIM_TALK_TEMPLATE_BUTTON_ID BIGINT,
    PRIMARY KEY (ID)
);

-- 관리자 접속 허용 IP
CREATE TABLE IF NOT EXISTS OP_ALLOW_IP (
    -- 접근허용 IP ID
    ALLOW_IP_ID                  INTEGER NOT NULL,
    -- 접근 타입 (1: 관리자, 2: 판매관리자)
    ACCESS_TYPE                  VARCHAR(1) NOT NULL,
    -- IP 주소
    REMOTE_ADDR                  VARCHAR(50) NOT NULL,
    -- 표시 여부(Y, N)
    DISPLAY_FLAG                 VARCHAR(1) NOT NULL,
    -- 등록자 ID
    CREATED_USER                 VARCHAR(50) NOT NULL,
    -- 등록일
    CREATED_DATE                 VARCHAR(14) NOT NULL,
    -- 수정자 ID
    UPDATED_USER                 VARCHAR(50),
    -- 수정일
    UPDATED_DATE                 VARCHAR(14),
    PRIMARY KEY (ALLOW_IP_ID)
);

CREATE TABLE IF NOT EXISTS OP_APPLICATION_INFO (
    ID                           BIGINT NOT NULL,
    CREATED                      TIMESTAMP,
    CREATED_BY                   BIGINT,
    UPDATED                      TIMESTAMP,
    UPDATED_BY                   BIGINT,
    APPLICATION_NO               VARCHAR(100) NOT NULL,
    APPLICATION_VERSION          VARCHAR(20) NOT NULL,
    DEVICE_TYPE                  VARCHAR(15),
    PUSH_TOKEN                   VARCHAR NOT NULL,
    USER_ID                      BIGINT,
    UUID                         VARCHAR(200) NOT NULL,
    PRIMARY KEY (ID)
);

-- 금지어
CREATE TABLE IF NOT EXISTS OP_BAN_WORD (
    -- 금지어 ID
    BAN_WORD_ID                  INTEGER NOT NULL,
    -- 금지어
    BAN_WORD                     VARCHAR(20) NOT NULL,
    -- 회원ID
    USER_ID                      BIGINT NOT NULL DEFAULT 0,
    -- 등록자명
    USERNAME                     VARCHAR(20),
    -- 등록일
    CREATION_DATE                VARCHAR(14),
    PRIMARY KEY (BAN_WORD_ID)
);

-- 배치실행
CREATE TABLE IF NOT EXISTS OP_BATCH_EXECUTION (
    -- 배치구분
    BATCH_TYPE                   VARCHAR(100) NOT NULL,
    -- 실행날짜
    EXECUTION_DATE               VARCHAR(8) NOT NULL,
    -- 시작시간
    START_TIME                   VARCHAR(8),
    -- 종료시간
    END_TIME                     VARCHAR(8),
    -- 결과 (1:정상처리 , 2:오류발생)
    RESULT                       VARCHAR(1),
    -- 오류내용
    MESSAGE                      TEXT,
    PRIMARY KEY (BATCH_TYPE, EXECUTION_DATE)
);

-- 배치 프로그램
CREATE TABLE IF NOT EXISTS OP_BATCH_JOB (
    -- 배치 작업 ID
    BATCH_JOB_ID                 INTEGER NOT NULL,
    -- 작업명
    JOB_NAME                     VARCHAR(100) NOT NULL,
    -- 작업 실행 메서드명
    JOB_METHOD                   VARCHAR(100) NOT NULL,
    -- 트리거 종류 (1: 심플, 2: 크론)
    TRIGGER_TYPE                 VARCHAR(1) NOT NULL,
    -- 반복시간 (초, 심플인 경우)
    TRIGGER_REPEAT_SECONDS       VARCHAR(20),
    -- 반복 표현식 (크론인 경우)
    TRIGGER_CRON_EXPRESSION      VARCHAR(50),
