    CREATED_BY                   BIGINT,
    UPDATED                      TIMESTAMP,
    UPDATED_BY                   BIGINT,
    APPLICATION_NO               VARCHAR(100),
    APPLICATION_VERSION          VARCHAR(20),
    BATCH_DATE                   TIMESTAMP,
    DEVICE_TYPE                  VARCHAR(15),
    KAKAO_SENT                   BIGINT,
    KAKAO_SUCCESS                BIGINT,
    MMS_SENT                     BIGINT,
    MMS_SUCCESS                  BIGINT,
    ORDER_AMOUNT                 BIGINT,
    ORDER_COUNT                  BIGINT,
    PHONE_NUMBER                 VARCHAR(140),
    POINT                        BIGINT,
    PUSH_RECEIVE                 BIGINT,
    PUSH_SENT                    BIGINT,
    PUSH_SUCCESS                 BIGINT,
    PUSH_TOKEN                   VARCHAR,
    RECEIVE_PUSH                 VARCHAR(1),
    RECEIVE_SMS                  VARCHAR(1),
    REDIRECTION                  BIGINT,
    SMS_SENT                     BIGINT,
    SMS_SUCCESS                  BIGINT,
    STATISTICS_DATE              VARCHAR(255),
    USER_NAME                    VARCHAR(350),
    UUID                         VARCHAR(200),
    PRIMARY KEY (CAMPAIGN_ID, USER_ID)
);

-- 카드 혜택
CREATE TABLE IF NOT EXISTS OP_CARD_BENEFITS (
    -- 카드 혜택 ID
    BENEFITS_ID                  INTEGER NOT NULL,
    -- 제목
    SUBJECT                      VARCHAR(50),
    -- 내용
    CONTENT                      VARCHAR,
    -- 노출 시작일
    START_DATE                   VARCHAR(10),
    -- 노출 종료일
    END_DATE                     VARCHAR(10),
    -- 생성일
    CREATED_DATE                 VARCHAR(12),
    PRIMARY KEY (BENEFITS_ID)
);

-- 공통코드
CREATE TABLE IF NOT EXISTS OP_COMMON_CODE (
    -- 코드구분
    CODE_TYPE                    VARCHAR(30) NOT NULL,
    -- 언어
    LANGUAGE                     VARCHAR(2) NOT NULL,
    -- 코드값
    ID                           VARCHAR(25) NOT NULL,
    -- 코드라벨
    LABEL                        VARCHAR(255),
    -- 코드상세
    DETAIL                       VARCHAR(255),
    -- 정렬순서
