    -- 사용유무 (Y:사용, N:사용안함)
    USE_YN                       VARCHAR(1) DEFAULT 'Y',
    -- 상위ID
    UP_ID                        VARCHAR(25),
    -- 코드값
    CODE_VALUE                   VARCHAR(255),
    -- 확장코드
    EXTENSION_CODE               VARCHAR(255),
    -- 매핑코드
    MAPPING_CODE                 VARCHAR(255),
    PRIMARY KEY (CODE_TYPE, LANGUAGE, ID)
);

-- 공통메세지
CREATE TABLE IF NOT EXISTS OP_COMMON_MESSAGE (
    -- 메세지 ID
    ID                           VARCHAR(20) NOT NULL,
    -- 언어
    LANGUAGE                     VARCHAR(20) NOT NULL,
    -- 메세지 내용
    MESSAGE                      VARCHAR(255) NOT NULL,
    PRIMARY KEY (ID, LANGUAGE)
);

CREATE TABLE IF NOT EXISTS OP_COMMUNITY_COMMENT (
    BOARD_COMMENT_ID             BIGINT NOT NULL,
    PARENT_COMMENT_ID            BIGINT,
    BOARD_ID                     INTEGER NOT NULL,
    BOARD_CODE                   VARCHAR(20),
