);

-- 상점 정보
CREATE TABLE IF NOT EXISTS OP_CONFIG (
    -- 상점 환경설정 ID
    SHOP_CONFIG_ID               BIGINT NOT NULL,
    -- 상점명
    SHOP_NAME                    VARCHAR(50) NOT NULL,
    -- 회사명
    COMPANY_NAME                 VARCHAR(50) NOT NULL,
    -- 대표자명
    BOSS_NAME                    VARCHAR(30) NOT NULL,
    -- 업태
    CATEGORY_TYPE                VARCHAR(255) NOT NULL,
    -- 업종
    BUSINESS_TYPE                VARCHAR(255) NOT NULL,
    -- 전화번호
    TEL_NUMBER                   VARCHAR(20) NOT NULL,
    -- 팩스번호
    FAX_NUMBER                   VARCHAR(20),
    -- 우편번호
    POST                         VARCHAR(8) NOT NULL,
    -- 도도부현
    DODOBUHYUN                   VARCHAR(8) NOT NULL,
    -- 주소
    ADDRESS                      VARCHAR(100) NOT NULL,
    -- 상세 주소
    ADDRESS_DETAIL               VARCHAR(50) DEFAULT '',
    -- 관리자 이름
    USERNAME                     VARCHAR(30) DEFAULT '',
    -- 관리자 이메일
    EMAIL                        VARCHAR(50) DEFAULT '',
    -- 사업자등록번호
    COMPANY_NUMBER               VARCHAR(30),
    -- 통신판매업신고번호
    MAIL_ORDER_NUMBER            VARCHAR(30),
    -- 소스공개여부(0:공개,1:비공개)
    SOURCE_OPEN                  VARCHAR(1) DEFAULT '0',
    -- 썸네일 설정(1:사이즈별 썸네일 저장, 2:사이즈별 썸네일 저장)
    THUMBNAIL_TYPE               VARCHAR(1) NOT NULL DEFAULT '1',
    -- 썸네일 사이즈 정보
    THUMBNAIL_SIZE               VARCHAR(255),
    -- 가입 차단ID
    DENIED_ID                    TEXT,
    -- 결제수단ID PG사 선택(Veritrans)
    PAYMENT_ID                   VARCHAR(25) NOT NULL,
    -- 신용카드(0:사용 안함, 1: 사용)
    PAYMENT_CARD                 VARCHAR(1) DEFAULT '0',
    -- 온라인입금(0:사용 안함, 1: 사용)
    PAYMENT_BANK                 VARCHAR(1) DEFAULT '0',
    -- 가상계좌
    PAYMENT_VBANK                VARCHAR(1) DEFAULT '0',
    -- 에스크로 사용여부
    PAYMENT_ESCROW               VARCHAR(1) DEFAULT '0',
    -- 편의점(0:사용 안함, 1: 사용)
    PAYMENT_CONV                 VARCHAR(1) DEFAULT '0',
    -- 대금상환(0:사용 안함, 1: 사용)
    PAYMENT_DLV                  VARCHAR(1) DEFAULT '0',
    -- 실시간 계좌이체
    PAYMENT_REALTIME             VARCHAR(1) DEFAULT '0',
    -- 휴대폰
    PAYMENT_HP                   VARCHAR(1) DEFAULT '0',
    -- 사이트 최소 결재 금액
    MINIMUM_PAYMENT_AMOUNT       INTEGER,
    -- 지금기한
    PAYMENT_CONV_LIMIT           VARCHAR(1),
    -- 등록일
    CREATED_DATE                 VARCHAR(14) NOT NULL DEFAULT '00000000000000',
    -- 회원가입 약관
    AGREEMENT                    TEXT,
    -- 특정상거래법
    TRADER_RAW                   TEXT,
    -- 개인정보 취급 방침
    PROTECT_POLICY               TEXT,
    DELIVERY_INFO                TEXT,
    -- 컨버전 테크 Overture
    TAG_OVERTURE                 TEXT,
    -- 컨버전 태그 Adwords
    TAG_ADWORDS                  TEXT,
    -- 상담전화
    COUNSEL_TEL_NUMBER           VARCHAR(20),
    -- 관리자 전화
    ADMIN_TEL_NUMBER             VARCHAR(20),
    -- 개인정보관리자
    ADMIN_NAME                   VARCHAR(30),
    -- 관리자 이메일
    ADMIN_EMAIL                  VARCHAR(50),
    -- 사이트 타이틀
    SEO_TITLE                    VARCHAR(255) DEFAULT '',
    -- 메타 keywords
    SEO_KEYWORDS                 VARCHAR(255),
    -- 메타 description
    SEO_DESCRIPTION              VARCHAR(255),
    -- H1
    SEO_HEADER_CONTENTS1         VARCHAR(255),
    -- 테마워드 타이틀
    SEO_THEMAWORD_TITLE          VARCHAR(255),
    -- 테마워드 설명
    SEO_THEMAWORD_DESCRIPTION    VARCHAR(255),
    -- 소스 공개 여부 (Y : 사용, N : 사용 안함)
    SOURCE_FLAG                  VARCHAR(1) DEFAULT 'N',
    -- TOP 공통배너 링크
    TOP_BANNER_LINK              VARCHAR(255),
    -- TOP 공통배너 이미지명
    TOP_BANNER_IMAGE             VARCHAR(255),
    -- TOP 공통배너 색상
    TOP_BANNER_COLOR             VARCHAR(20),
    -- 우측 공통배너 링크
    RIGHT_BANNER_LINK            VARCHAR(255),
    -- 우측 공통배너 이미지명
    RIGHT_BANNER_IMAGE           VARCHAR(255),
    -- 적립금설정(1:비율, 2:금액)
    POINT_DEFAULT_TYPE           VARCHAR(1) DEFAULT '1',
    -- 기본적립금
    POINT_DEFAULT                DOUBLE PRECISION,
    -- 특정일 시작시간
    REPEAT_DAY_START_TIME        VARCHAR(2) DEFAULT '00',
    -- 특정일 종료시간
    REPEAT_DAY_END_TIME          VARCHAR(2) DEFAULT '23',
    -- 회원가입시 적립금
    POINT_JOIN                   INTEGER,
    -- 리뷰채택시 적립금
    POINT_REVIEW                 INTEGER,
    -- 포토리뷰채틱시 적립금
    PHOTO_POINT_REVIEW           INTEGER,
    -- 리뷰 노출 설정 (1:즉시 노출, 2:관리자 승인 후 노출)
    REVIEW_DISPLAY_TYPE          VARCHAR(1) DEFAULT '2',
    -- 첫 구매시 적립금
    POINT_FIRST_BUY              INTEGER,
    -- 방문시 적립금(일별)
    POINT_VISIT_DAY              INTEGER,
    -- 추천인 적립금액
    POINT_RECOMMEND              INTEGER,
    POINT_RECOMMEND_PRICE        INTEGER,
    -- 적립금 지급시기
    POINT_SAVE_AFTER_DAY         INTEGER DEFAULT -1,
    -- 적립금 적립시기 설정(1:결제완료시, 2:배송완료시)
    POINT_SAVE_TIME              VARCHAR(1) NOT NULL DEFAULT '1',
    -- 적립금 지급제한(1:조건없음, 2:결제시 포인트 사용하면 포인트을 지급하지 않음)
    POINT_SAVE_TYPE              VARCHAR(1) NOT NULL DEFAULT '1',
    -- 적립금 최저 사용금액
    POINT_USE_MIN                INTEGER DEFAULT -1,
    -- 적립금 최대 사용금액
    POINT_USE_MAX                INTEGER DEFAULT -1,
    -- 적립금 만료일
    POINT_EXPIRATION_MONTH       INTEGER DEFAULT -1,
    -- 배송쿠폰 만료일
    SHIPPING_COUPON_EXP_MONTH    INTEGER DEFAULT -1,
    -- 소비세
    TAX                          INTEGER NOT NULL DEFAULT 8,
    -- 소비세 설정(1:반올림, 2:그대로)
    TAX_TYPE                     VARCHAR(1) NOT NULL DEFAULT '1',
    -- 소비세 포함여부 표시 방법 (1:세금포함, 2:세금별도)
    TAX_DISPLAY_TYPE             VARCHAR(1) NOT NULL,
    -- 재고량 차감 기능 사용 여부 (Y : 사용, N : 사용 안함)
    STOCK_QUANTITY_FLAG          VARCHAR(1) DEFAULT 'Y',
    -- 로그인 varchar(65535) 영역
    LOGIN_TEXT                   VARCHAR(255),
    -- 쿠폰 사용 여부
    USE_COUPON_FLAG              VARCHAR(1) DEFAULT 'Y',
    -- 회원가입 약관 HTML영역
    USER_HTML_EDIT               VARCHAR,
    -- 배송희망일 사용여부(Y:사용, N:사용안함)
    DELIVERY_HOPE_FLAG           VARCHAR(1) DEFAULT 'N',
    -- 배송희망 시작일
    DELIVERY_HOPE_START_DATE     VARCHAR(2),
    -- 배송희망 종료
    DELIVERY_HOPE_END_DATE       VARCHAR(2),
    -- 구매확정 요청 메시지 발송일 설정
    CONFIRM_PURCHASE_REQUEST_DATE VARCHAR(2),
    -- 구매확정일 설정
    CONFIRM_PURCHASE_DATE        VARCHAR(2),
    -- 네이버 페이 사용여부
    NAVER_PAY_FLAG               VARCHAR(1),
    -- 매출 기준상태 (0 : 주문 등록시, 10 : 결제 확인, 20 : 배송 준비)
    REVENUE_SALES_STATUS         VARCHAR(2),
    -- 금지어 (,)콤마로 구분하여 저장.
    BAN_WORD                     TEXT,
    -- 입금 마감일
    BANK_DEPOSIT_DUE_DAY         INTEGER DEFAULT 7,
    -- 옵션 최대 개수
    OPTION_QUANTITY              INTEGER,
    -- 포인트 사용비율
    POINT_USE_RATIO              INTEGER,
    -- 카테고리 업데이트 일자
    CATEGORY_UPDATED_DATE        VARCHAR(14),
    -- 임시 주문정보 유지기간
    RETENTION_PERIOD             INTEGER NOT NULL DEFAULT 60,
    -- 배송완료일 설정
    SHIPPING_COMPLETE_DATE       VARCHAR(2) DEFAULT '7',
    ALTERNATE_SYSTEM             INTEGER,
    -- 스마트택배 대상 조회기준일
    SMART_DELIVERY_CRITERIA_DATE VARCHAR(2) DEFAULT '2',
    PRIMARY KEY (SHOP_CONFIG_ID)
);

