    SUBJECT                      VARCHAR(255) NOT NULL,
    -- URL
    URL                          VARCHAR(255),
    -- 카테고리 팀
    CATEGORY_TEAM                VARCHAR(255),
    -- 사용자명
    USER_NAME                    VARCHAR(30),
    -- 비밀번호
    PASSWORD                     VARCHAR(64),
    -- 이메일
    EMAIL                        VARCHAR(50),
    -- 내용
    CONTENT                      VARCHAR,
    -- 조회수
    HITS                         INTEGER DEFAULT 0,
    -- 게시판 코드
    BOARD_CODE                   VARCHAR(20),
    -- 서브 카테고리
    SUB_CATEGORY                 INTEGER DEFAULT 0,
    -- 타겟 옵션
    TARGET_OPTION                VARCHAR(1) DEFAULT 'N',
    -- rel 옵션
    REL_OPTION                   VARCHAR(1) DEFAULT 'N',
    -- 공지 여부
    NOTICE_FLAG                  VARCHAR(1) DEFAULT 'N',
    -- 판매자별 노출여부
    SELLER_SELECT_FLAG           VARCHAR(1) DEFAULT 'N',
    -- 노출위치 (1: 전체, 2: 사용자, 3: 판매자)
    VISIBLE_TYPE                 INTEGER DEFAULT 1,
    -- 등록일
    CREATED_DATE                 VARCHAR(14),
    -- 지자체코드
    LOCGOV_CODE                  VARCHAR(10),
    -- 사용여부
    USE_YN                       VARCHAR(1) DEFAULT 'Y',
    PRIMARY KEY (NOTICE_ID)
);

-- 판매자 공지사항
