-- 팝업
CREATE TABLE IF NOT EXISTS OP_POPUP (
    -- 팝업ID
    POPUP_ID                     BIGINT NOT NULL,
    -- 팝업상태(1:사용, 2:일시정지, 3:종료)
    POPUP_CLOSE                  VARCHAR(1) NOT NULL,
    -- 팝업타입(1:윈도우, 2:레이어)
    POPUP_TYPE                   VARCHAR(1) NOT NULL,
    -- 팝업형태(1:텍스트입력, 2:텍스트입력-테두리없음, 3:이미지등록)
    POPUP_STYLE                  VARCHAR(1) NOT NULL,
    -- 팝업제목
    SUBJECT                      VARCHAR(200),
    -- 팝업내용
    CONTENT                      VARCHAR,
    -- 시작일
    START_DATE                   VARCHAR(14),
    -- 시작시간
    START_TIME                   VARCHAR(2) DEFAULT '00',
    -- 종료일
    END_DATE                     VARCHAR(14),
    -- 종료시간
    END_TIME                     VARCHAR(2) DEFAULT '00',
    -- 가로
    WIDTH                        INTEGER DEFAULT 0,
    -- 세로
    HEIGHT                       INTEGER DEFAULT 0,
    -- 위에서
    TOP_POSITION                 INTEGER DEFAULT 0,
    -- 왼쪽에서
    LEFT_POSITION                INTEGER DEFAULT 0,
    -- 팝업 이미지
    POPUP_IMAGE                  VARCHAR(255),
    -- 이미지 링크
    IMAGE_LINK                   VARCHAR(255),
    -- 배경색
    BACKGROUND_COLOR             VARCHAR(20),
    PRIMARY KEY (POPUP_ID)
);

