-- 문의관리
CREATE TABLE IF NOT EXISTS OP_QNA (
    -- 문의 ID
    QNA_ID                       INTEGER NOT NULL,
    -- 1차 분류(1: 배송지연 , 2:반품문의, 3:A/S문의, 4:환불문의, 5:주문결제문의, 6:회원정보문의, 7:취소문의, 8:교환문의, 9:기타문의 0: 상품평)
    QNA_GROUP                    VARCHAR(10) NOT NULL,
    -- 2차 분류(1차분류별 상세분류)
    QNA_TYPE                     VARCHAR(1),
    -- 제목
    SUBJECT                      VARCHAR(200) NOT NULL,
    -- 문의내용
    QUESTION                     VARCHAR(1000) NOT NULL,
    -- 회원ID
    USER_ID                      BIGINT NOT NULL DEFAULT 0,
    -- 문의자 이름
    USER_NAME                    VARCHAR(350) NOT NULL,
    -- 판매자ID
    SELLER_ID                    BIGINT DEFAULT 0,
    -- 문의자 이메일
    EMAIL                        VARCHAR(840) NOT NULL,
    -- 상품 ID
    ITEM_ID                      INTEGER,
    -- 주문번호
    ORDER_CODE                   VARCHAR(40),
    -- 문의답변 수
    ANSWER_COUNT                 INTEGER NOT NULL DEFAULT 0,
    -- 비밀글 여부 (Y:비밀글, N:일반)
    SECRET_FLAG                  VARCHAR(1) DEFAULT 'N',
    -- 문의 공개여부(Y:공개, N:비공개)
    DISPLAY_FLAG                 VARCHAR(1) NOT NULL DEFAULT 'Y',
    -- 작성일
    CREATED_DATE                 VARCHAR(14),
    -- 0 : 정상 1: 삭제
    DATA_STATUS_CODE             VARCHAR(1) DEFAULT '0',
    -- 문의 이미지
    QNA_IMAGE                    VARCHAR(255),
    -- 사용여부(게시여부)
    USE_YN                       VARCHAR(1) DEFAULT 'Y',
    -- 조회수
    HITS                         INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (QNA_ID)
);

-- 문의 답변
CREATE TABLE IF NOT EXISTS OP_QNA_ANSWER (
    -- 문의 답변 ID
    QNA_ANSWER_ID                INTEGER NOT NULL,
