    SEND_SMS_FLAG                VARCHAR(1) DEFAULT 'N',
    -- 답변완료 메일전송 여부(Y:전송함, N:전송하지않음)
    SEND_MAIL_FLAG               VARCHAR(1) DEFAULT 'N',
    -- 답변일
    ANSWER_DATE                  VARCHAR(14) NOT NULL,
    -- 0 : 정상 1: 삭제
    DATA_STATUS_CODE             VARCHAR(1) NOT NULL DEFAULT '0',
    -- 조회수
    HITS                         INTEGER NOT NULL DEFAULT 0,
    -- 비밀글여부
    SECRET_FLAG                  VARCHAR(1) DEFAULT 'N',
    PRIMARY KEY (QNA_ANSWER_ID)
);

