    INQUIRY_CONTENT     TEXT,
    ANSWER_FLAG         INTEGER,          -- guess: compared as 0/1 int (I.ANSWER_FLAG = 1 / = 0), Java field is int not Y/N char
    INQUIRY_IMG         VARCHAR(255),
