    INSTT_CRT_DOC_ID     VARCHAR(255),
    PRVC_IDNTFC_INFO     VARCHAR(255),
    PRVC_IDNTFC_SE_CD    VARCHAR(20),
    SNDNG_CNTNTS         TEXT,
    IMG1_URL_INFO        VARCHAR(500),
    IMG2_URL_INFO        VARCHAR(500),
