ON CONFLICT (CODE_TYPE, CODE_LANGUAGE, ID) DO NOTHING;

INSERT INTO ADMIN_COMMON_CODE (CODE_TYPE, CODE_LANGUAGE, ID, LABEL, ORDERING, USE_YN) VALUES
('POPUP_TYPE', 'ko', 'NOTICE', '공지형', 1, 'Y'),
