-- =====================================================================
-- Round 5: 외부 연계시스템 (매직라인4웹 PKI 인증서 로그인, NH농협 데이터 연계 배치).
-- 매직라인4웹은 브라우저 플러그인이 로컬 인증서 저장소를 읽어 서버에 인증서를
-- 넘기는 방식이라, 인증서 파싱/담당자 매칭 자체는 방화벽 없이도 동작한다 - 다만
-- 실제 정부 PKI 루트 CA에 대한 OCSP 폐기여부 조회는 연계(외부망) 대상이라
-- ghlove.integrations.magicline.ocsp-enabled=false 동안은 생략한다.
-- =====================================================================
CREATE TABLE IF NOT EXISTS LOCGOV_OFFICER (
    CERT_SUBJECT_DN   VARCHAR(500) PRIMARY KEY,
    LOCGOV_CODE       VARCHAR(50)  NOT NULL,
    OFFICER_NAME      VARCHAR(255) NOT NULL,
    USE_YN            CHAR(1)      NOT NULL DEFAULT 'Y',
    CREATED_DATE      TIMESTAMP    NOT NULL DEFAULT now()
);

-- NH농협 데이터 연계(기부자 CI/금액을 NH가 소유한 별도 DB로 야간 배치 반출 -
-- AS-IS NhApiBatchServiceImpl.setUserCntrForNh, DB-level 연계). admin은
-- donation 서비스 DB를 직접 읽을 수 없어(DB per Service), 이미 구축된
-- STAT_DONATION_LEDGER(통계 ReadModel, donation.lifecycle 이벤트로 채워짐)를
-- 원천 데이터로 쓴다.
CREATE TABLE IF NOT EXISTS NH_EXPORT_LOG (
    CNTR_SN         VARCHAR(50)  PRIMARY KEY,
    USER_ID         BIGINT,
    LOCGOV_CODE     VARCHAR(50),
    AMOUNT          NUMERIC(15,2),
    EXPORT_STATUS   VARCHAR(20)  NOT NULL, -- SENT / MOCK
    EXPORTED_DATE   TIMESTAMP    NOT NULL DEFAULT now()
);

-- 데모용 지자체 담당자 인증서 매핑 (실제 인증서 대신 로컬에서 발급한 self-signed
-- 테스트 인증서의 Subject DN을 등록해 두면 curl로 흐름을 끝까지 검증할 수 있다).
-- Java X509Certificate.getSubjectX500Principal().getName()의 기본(RFC2253) 출력은
-- OpenSSL의 "CN=...,O=...,C=..." 순서를 뒤집어 "C=...,O=...,CN=..." 순으로 주고,
-- 콤마 뒤에 공백도 없다 - 실제 curl 검증 중 발견(값이 달라 최초 로그인 시도가
-- "등록되지 않은 인증서입니다" 로 실패했었음).
INSERT INTO LOCGOV_OFFICER (CERT_SUBJECT_DN, LOCGOV_CODE, OFFICER_NAME, USE_YN) VALUES
('C=KR,O=Gangnam-gu,CN=강남구청 담당자', '11230', '김민준', 'Y')
ON CONFLICT (CERT_SUBJECT_DN) DO NOTHING;

-- 스마트택배 배송조회 화면(SmartDeliveryClient)용 택배사 코드 - order 서비스의
-- 동일한 DELIVERY_CARRIER 코드를 그대로 복사(DB per Service라 조회로 공유 불가).
INSERT INTO ADMIN_COMMON_CODE (CODE_TYPE, CODE_LANGUAGE, ID, LABEL, ORDERING, USE_YN) VALUES
('DELIVERY_CARRIER', 'ko', 'CJ',    'CJ대한통운', 1, 'Y'),
('DELIVERY_CARRIER', 'ko', 'POST',  '우체국택배', 2, 'Y'),
('DELIVERY_CARRIER', 'ko', 'HANJIN','한진택배',   3, 'Y'),
('DELIVERY_CARRIER', 'ko', 'LOTTE', '롯데택배',   4, 'Y')
ON CONFLICT (CODE_TYPE, CODE_LANGUAGE, ID) DO NOTHING;

-- =====================================================================
-- Round 6 (SFR-007/009 gap fill): 통계 ReadModel을 point.ledger/gift.lifecycle
-- 이벤트로 확장 - 지금까지 admin은 donation.lifecycle/order.saga만 구독했다.
-- STAT_POINT_LEDGER는 원장행 자체가 불변이라 append-only(PK=원본 LEDGER_ID),
-- STAT_GIFT_LEDGER는 답례품의 "현재 상태" 사본이라 itemId로 upsert한다.
-- =====================================================================
CREATE TABLE IF NOT EXISTS STAT_POINT_LEDGER (
    LEDGER_ID     BIGINT       PRIMARY KEY,
    USER_ID       BIGINT,
    LOCGOV_CODE   VARCHAR(50),
    TXN_TYPE      VARCHAR(20),
    POINT_AMOUNT  BIGINT,
    CREATED_DATE  TIMESTAMP    NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS STAT_GIFT_LEDGER (
    ITEM_ID           BIGINT       PRIMARY KEY,
    SELLER_ID         BIGINT,
    CATEGORY_CODE     VARCHAR(50),
    DATA_STATUS_CODE  VARCHAR(20),
    SALE_PRICE        INTEGER,
    UPDATED_DATE      TIMESTAMP    NOT NULL DEFAULT now()
);

-- =====================================================================
-- Round 7 (마이페이지 상세화면 7종 중 "1:1 문의"): OP_QNA/OP_QNA_ANSWER/OP_QNA_FILE는
-- 이미 위쪽 배치 스캔 구간(schema.sql에서 그대로 옮겨온)에 정의돼 있었지만 PK 컬럼에
-- 시퀀스가 없었다(레거시 배치 스캔은 시퀀스까지는 못 잡아냄) - 다른 admin 테이블들과
-- 동일한 컨벤션으로 추가한다. 일반 1:1문의는 ITEM_ID/SELLER_ID/ORDER_CODE를 비워둔다
-- (AS-IS도 같은 테이블을 답례품별/주문별 문의에도 재사용하지만 이번 라운드는 마이페이지
-- 일반 문의만 다룬다).
-- =====================================================================
CREATE SEQUENCE IF NOT EXISTS op_qna_qna_id_seq START WITH 1000;

ALTER TABLE OP_QNA ALTER COLUMN QNA_ID SET DEFAULT nextval('op_qna_qna_id_seq');

ALTER SEQUENCE op_qna_qna_id_seq OWNED BY OP_QNA.QNA_ID;

CREATE SEQUENCE IF NOT EXISTS op_qna_answer_qna_answer_id_seq START WITH 1000;

ALTER TABLE OP_QNA_ANSWER ALTER COLUMN QNA_ANSWER_ID SET DEFAULT nextval('op_qna_answer_qna_answer_id_seq');

ALTER SEQUENCE op_qna_answer_qna_answer_id_seq OWNED BY OP_QNA_ANSWER.QNA_ANSWER_ID;

CREATE SEQUENCE IF NOT EXISTS op_qna_file_qna_file_id_seq START WITH 1000;

ALTER TABLE OP_QNA_FILE ALTER COLUMN QNA_FILE_ID SET DEFAULT nextval('op_qna_file_qna_file_id_seq');

ALTER SEQUENCE op_qna_file_qna_file_id_seq OWNED BY OP_QNA_FILE.QNA_FILE_ID;

