INSERT INTO OP_COMMUNITY_LOCGOVFAQ (ID, SUBJECT, CONTENT, FAQ_TYPE, USE_YN, CREATED_DATE, UPDATED_DATE, HITS)
VALUES
(1, '회원가입은 어떻게 하나요?', '상단 GNB의 ''회원가입'' 버튼을 클릭한 뒤 본인인증(휴대폰 또는 아이핀)을 완료하시면 가입하실 수 있습니다.', 'JOIN', 'Y', now() - (1 || ' days')::interval, now() - (1 || ' days')::interval, 12),
(2, '만 14세 미만도 가입할 수 있나요?', '만 14세 미만은 법정대리인 동의 절차가 필요하며, 현재 온라인 가입은 만 14세 이상만 가능합니다.', 'JOIN', 'Y', now() - (2 || ' days')::interval, now() - (2 || ' days')::interval, 19),
(3, '아이디를 잊어버렸어요.', '로그인 화면의 ''아이디 찾기''에서 본인인증을 통해 아이디를 확인하실 수 있습니다.', 'JOIN', 'Y', now() - (3 || ' days')::interval, now() - (3 || ' days')::interval, 26),
(4, '비밀번호를 잊어버렸어요.', '로그인 화면의 ''비밀번호 찾기''에서 본인인증 후 임시 비밀번호를 발급받아 재설정하실 수 있습니다.', 'JOIN', 'Y', now() - (4 || ' days')::interval, now() - (4 || ' days')::interval, 33),
(5, '외국인도 회원가입이 가능한가요?', '외국인등록번호 또는 거소신고번호로 본인인증을 완료하면 가입 및 기부가 가능합니다.', 'JOIN', 'Y', now() - (5 || ' days')::interval, now() - (5 || ' days')::interval, 40),
(6, '회원 탈퇴는 어떻게 하나요?', '마이페이지 > 회원정보수정 화면 하단의 ''회원탈퇴'' 버튼을 통해 탈퇴하실 수 있습니다.', 'JOIN', 'Y', now() - (6 || ' days')::interval, now() - (6 || ' days')::interval, 47),
(7, '간편인증 로그인이 안 돼요.', '이용 중인 인증서 앱이 최신 버전인지 확인해 주시고, 계속 실패할 경우 고객센터로 문의해 주세요.', 'JOIN', 'Y', now() - (7 || ' days')::interval, now() - (7 || ' days')::interval, 54),
(8, '휴대폰 번호가 변경됐어요. 어떻게 하나요?', '마이페이지 > 회원정보수정에서 휴대폰 번호를 변경하실 수 있습니다.', 'JOIN', 'Y', now() - (8 || ' days')::interval, now() - (8 || ' days')::interval, 61),
(9, '이메일 주소도 변경할 수 있나요?', '네, 마이페이지 > 회원정보수정에서 이메일 주소를 변경하실 수 있습니다.', 'JOIN', 'Y', now() - (9 || ' days')::interval, now() - (9 || ' days')::interval, 68),
(10, '탈퇴한 계정으로 다시 가입할 수 있나요?', '탈퇴 후 일정 기간이 지나면 동일한 본인인증 정보로 재가입이 가능합니다.', 'JOIN', 'Y', now() - (10 || ' days')::interval, now() - (10 || ' days')::interval, 75),
(11, '하루에 여러 번 기부할 수 있나요?', '네, 연간 기부한도 내에서 횟수 제한 없이 기부하실 수 있습니다.', 'DONATE', 'Y', now() - (11 || ' days')::interval, now() - (11 || ' days')::interval, 82),
(12, '기부 금액에 제한이 있나요?', '개인별 연간 기부한도는 2천만원이며, 1회 최소 기부금액은 100원입니다.', 'DONATE', 'Y', now() - (12 || ' days')::interval, now() - (12 || ' days')::interval, 89),
(13, '본인 주소지 지자체에는 기부할 수 없나요?', '네, 고향사랑기부금법에 따라 주민등록상 주소지 지자체에는 기부하실 수 없습니다.', 'DONATE', 'Y', now() - (13 || ' days')::interval, now() - (13 || ' days')::interval, 96),
(14, '기부금은 취소할 수 있나요?', '결제 완료 전(신청 상태)에는 취소가 가능하나, 납부가 완료된 기부금은 반환·취소되지 않습니다.', 'DONATE', 'Y', now() - (14 || ' days')::interval, now() - (14 || ' days')::interval, 103),
(15, '법인도 기부할 수 있나요?', '고향사랑기부금은 개인만 기부 가능하며, 법인은 기부 대상이 아닙니다.', 'DONATE', 'Y', now() - (15 || ' days')::interval, now() - (15 || ' days')::interval, 110),
(16, '기부금 납부 시간에 제한이 있나요?', '기부 가능 시간은 매일 01:00~23:30이며, 그 외 시간은 시스템 점검으로 이용이 제한됩니다.', 'DONATE', 'Y', now() - (16 || ' days')::interval, now() - (16 || ' days')::interval, 117),
(17, '특정사업 기부와 일반기부의 차이는 무엇인가요?', '일반기부는 지자체에 자유롭게 사용처를 맡기는 기부이고, 특정사업 기부는 지자체가 지정한 목적사업에 사용됩니다.', 'DONATE', 'Y', now() - (17 || ' days')::interval, now() - (17 || ' days')::interval, 124),
(18, '기부금 결제 수단은 무엇이 있나요?', '신용카드, 실시간 계좌이체 등 전자결제와 농협은행 창구를 통한 오프라인 납부를 지원합니다.', 'DONATE', 'Y', now() - (18 || ' days')::interval, now() - (18 || ' days')::interval, 131),
(19, '미성년자도 기부할 수 있나요?', '본인 명의 결제수단이 있는 경우 미성년자도 기부가 가능하나, 세액공제는 소득이 있는 경우에만 적용됩니다.', 'DONATE', 'Y', now() - (19 || ' days')::interval, now() - (19 || ' days')::interval, 138),
(20, '기부 후 영수증은 바로 발급되나요?', '결제 완료 후 마이페이지 > 기부확인증에서 바로 출력하실 수 있습니다.', 'DONATE', 'Y', now() - (20 || ' days')::interval, now() - (20 || ' days')::interval, 145),
(21, '기부포인트는 얼마나 적립되나요?', '기부금액의 일정 비율(지자체별 상이)이 답례품 구매에 사용할 수 있는 포인트로 적립됩니다.', 'POINT', 'Y', now() - (21 || ' days')::interval, now() - (21 || ' days')::interval, 152),
(22, '포인트 유효기간이 있나요?', '기부포인트는 적립일로부터 일정 기간(지자체별 정책에 따름) 내 사용하지 않으면 소멸될 수 있습니다.', 'POINT', 'Y', now() - (22 || ' days')::interval, now() - (22 || ' days')::interval, 159),
(23, '포인트는 다른 지자체에서도 쓸 수 있나요?', '아니요, 기부한 지자체의 답례품몰에서만 사용하실 수 있습니다.', 'POINT', 'Y', now() - (23 || ' days')::interval, now() - (23 || ' days')::interval, 166),
(24, '포인트 잔액은 어디서 확인하나요?', '마이페이지 > 기부포인트 조회 화면에서 지자체별 잔여 포인트를 확인하실 수 있습니다.', 'POINT', 'Y', now() - (24 || ' days')::interval, now() - (24 || ' days')::interval, 173),
(25, '답례품을 제공받지 않으면 포인트가 적립되나요?', '아니요, ''답례품을 제공받지 않음''을 선택하시면 포인트가 적립되지 않습니다.', 'POINT', 'Y', now() - (25 || ' days')::interval, now() - (25 || ' days')::interval, 180),
(26, '포인트로 배송비도 결제할 수 있나요?', '배송비는 별도이며 포인트로는 답례품 금액만 결제 가능합니다.', 'POINT', 'Y', now() - (26 || ' days')::interval, now() - (26 || ' days')::interval, 187),
(27, '포인트 적립은 언제 반영되나요?', '기부금 결제완료 처리 이후 통상 1~3일 이내 반영됩니다.', 'POINT', 'Y', now() - (27 || ' days')::interval, now() - (27 || ' days')::interval, 194),
(28, '오프라인으로 기부하려면 어떻게 하나요?', '전국 농협은행 창구를 방문하여 고향사랑기부금 신청서를 작성하고 납부하실 수 있습니다.', 'OFFLINE', 'Y', now() - (28 || ' days')::interval, now() - (28 || ' days')::interval, 201),
(29, '오프라인 기부 시에도 답례품을 받을 수 있나요?', '네, 신청서 작성 시 답례품 제공 여부를 선택하실 수 있습니다.', 'OFFLINE', 'Y', now() - (29 || ' days')::interval, now() - (29 || ' days')::interval, 208),
(30, '오프라인 기부 영수증은 어떻게 받나요?', '농협은행 창구에서 즉시 발급받거나, 이후 홈페이지 마이페이지에서 재발급받으실 수 있습니다.', 'OFFLINE', 'Y', now() - (30 || ' days')::interval, now() - (30 || ' days')::interval, 215),
(31, '오프라인 기부도 온라인처럼 포인트가 적립되나요?', '네, 전산 반영 후 온라인 기부와 동일하게 포인트가 적립됩니다.', 'OFFLINE', 'Y', now() - (31 || ' days')::interval, now() - (31 || ' days')::interval, 222),
(32, '오프라인 기부 시 신분증이 꼭 필요한가요?', '네, 본인확인을 위해 신분증을 지참하셔야 합니다.', 'OFFLINE', 'Y', now() - (32 || ' days')::interval, now() - (32 || ' days')::interval, 229),
(33, '특정사업 기부는 어떻게 신청하나요?', 'GNB ''기부 > 특정사업에 기부하기''에서 원하는 사업을 선택 후 기부하실 수 있습니다.', 'DESIGNATED', 'Y', now() - (33 || ' days')::interval, now() - (33 || ' days')::interval, 236),
(34, '목표금액을 초과한 특정사업은 어떻게 되나요?', '초과 모금액은 다른 고향사랑기금 사업 재원으로 활용됩니다.', 'DESIGNATED', 'Y', now() - (34 || ' days')::interval, now() - (34 || ' days')::interval, 243),
(35, '목표금액을 못 채운 특정사업은 어떻게 되나요?', '사업 축소 또는 폐지가 가능하며, 폐지 시 모금액은 타 기금사업 재원으로 활용됩니다.', 'DESIGNATED', 'Y', now() - (35 || ' days')::interval, now() - (35 || ' days')::interval, 250),
(36, '특정사업 기부에도 답례품이 제공되나요?', '네, 일반기부와 동일하게 답례품 제공 여부를 선택하실 수 있습니다.', 'DESIGNATED', 'Y', now() - (36 || ' days')::interval, now() - (36 || ' days')::interval, 257),
(37, '특정사업에 응원 메시지를 남길 수 있나요?', '네, 기부 시 사업 페이지에서 응원 메시지를 함께 남기실 수 있습니다.', 'DESIGNATED', 'Y', now() - (37 || ' days')::interval, now() - (37 || ' days')::interval, 264),
(38, '세액공제는 얼마나 받을 수 있나요?', '10만원까지는 전액(100/110 공제), 10만원 초과분은 16.5% 세액공제가 적용됩니다.', 'TAX', 'Y', now() - (38 || ' days')::interval, now() - (38 || ' days')::interval, 271),
(39, '세액공제는 언제 받을 수 있나요?', '기부한 해당 연도 연말정산 또는 종합소득세 신고 시 공제받으실 수 있습니다.', 'TAX', 'Y', now() - (39 || ' days')::interval, now() - (39 || ' days')::interval, 278),
(40, '배우자 명의로 기부해도 제 세액공제에 포함되나요?', '아니요, 기부자 본인 명의로 기부한 금액만 본인의 세액공제 대상입니다.', 'TAX', 'Y', now() - (40 || ' days')::interval, now() - (40 || ' days')::interval, 285),
(41, '기부금 영수증은 어디서 발급받나요?', '마이페이지 > 기부확인증에서 직접 출력하거나 국세청 홈택스에서 자동 조회됩니다.', 'TAX', 'Y', now() - (41 || ' days')::interval, now() - (41 || ' days')::interval, 292),
(42, '결정세액이 없으면 세액공제를 못 받나요?', '네, 해당 연도 결정세액이 없는 경우(전액 환급 대상) 세액공제가 적용되지 않습니다.', 'TAX', 'Y', now() - (42 || ' days')::interval, now() - (42 || ' days')::interval, 299),
(43, '연말정산 간소화 서비스에도 자동 반영되나요?', '국세청 전자기부금 영수증 시스템에 연계되어 대부분 자동 반영됩니다.', 'TAX', 'Y', now() - (43 || ' days')::interval, now() - (43 || ' days')::interval, 306),
(44, '답례품은 언제 배송되나요?', '기부 완료 후 통상 2~4주 이내 순차 배송되며, 지자체·상품별로 상이할 수 있습니다.', 'GIFT', 'Y', now() - (44 || ' days')::interval, now() - (44 || ' days')::interval, 313),
(45, '답례품을 교환하거나 반품할 수 있나요?', '마이페이지 > 취소반품교환 메뉴에서 신청하실 수 있으며, 답례품 특성에 따라 제한될 수 있습니다.', 'GIFT', 'Y', now() - (45 || ' days')::interval, now() - (45 || ' days')::interval, 320),
(46, '답례품 목록은 어디서 확인하나요?', '답례품몰 GNB에서 지자체별 답례품을 확인하실 수 있습니다.', 'GIFT', 'Y', now() - (46 || ' days')::interval, now() - (46 || ' days')::interval, 327),
(47, '답례품 재고가 없으면 어떻게 되나요?', '품절 표시되며 재입고 시 다시 구매하실 수 있습니다.', 'GIFT', 'Y', now() - (47 || ' days')::interval, now() - (47 || ' days')::interval, 334),
(48, '답례품 구매 한도가 따로 있나요?', '기부로 적립된 포인트 한도 내에서 구매 가능하며 별도의 추가 한도는 없습니다.', 'GIFT', 'Y', now() - (48 || ' days')::interval, now() - (48 || ' days')::interval, 341),
(49, '주문 내역은 어디서 확인하나요?', '마이페이지 > 주문조회에서 확인하실 수 있습니다.', 'ORDER', 'Y', now() - (49 || ' days')::interval, now() - (49 || ' days')::interval, 348),
(50, '배송지를 변경할 수 있나요?', '배송 시작 전이라면 마이페이지 > 배송지 관리에서 변경하실 수 있습니다.', 'ORDER', 'Y', now() - (50 || ' days')::interval, now() - (50 || ' days')::interval, 355),
(51, '여러 답례품을 한 번에 주문할 수 있나요?', '네, 장바구니에 담아 한 번에 결제하실 수 있습니다.', 'ORDER', 'Y', now() - (51 || ' days')::interval, now() - (51 || ' days')::interval, 362),
(52, '배송 조회는 어떻게 하나요?', '마이페이지 > 주문조회에서 실시간 배송 현황을 확인하실 수 있습니다.', 'ORDER', 'Y', now() - (52 || ' days')::interval, now() - (52 || ' days')::interval, 369),
(53, '민간플랫폼(네이버, 카카오 등)에서도 기부할 수 있나요?', '네, 일부 민간플랫폼과 연계하여 기부하실 수 있으며 절차는 동일합니다.', 'PRIVATE', 'Y', now() - (53 || ' days')::interval, now() - (53 || ' days')::interval, 376),
(54, '민간플랫폼 기부도 세액공제를 받을 수 있나요?', '네, 고향사랑e음을 통한 기부와 동일하게 세액공제 대상입니다.', 'PRIVATE', 'Y', now() - (54 || ' days')::interval, now() - (54 || ' days')::interval, 383),
(55, '민간플랫폼에서 결제한 내역도 마이페이지에서 조회되나요?', '네, 연계된 플랫폼의 기부 내역도 마이페이지 기부내역 조회에서 함께 확인하실 수 있습니다.', 'PRIVATE', 'Y', now() - (55 || ' days')::interval, now() - (55 || ' days')::interval, 390),
(56, '사이트 접속이 안 돼요.', '브라우저 캐시 삭제 후 재접속해 보시고, 계속 문제가 있으면 고객센터로 문의해 주세요.', 'SYSTEM', 'Y', now() - (56 || ' days')::interval, now() - (56 || ' days')::interval, 397),
(57, '어떤 브라우저를 지원하나요?', '크롬, 엣지, 웨일 등 최신 브라우저를 지원하며 인터넷 익스플로러는 지원이 종료되었습니다.', 'SYSTEM', 'Y', now() - (57 || ' days')::interval, now() - (57 || ' days')::interval, 404),
(58, '모바일에서도 이용할 수 있나요?', '네, 모바일 웹 및 반응형 화면으로 이용하실 수 있습니다.', 'SYSTEM', 'Y', now() - (58 || ' days')::interval, now() - (58 || ' days')::interval, 11),
(59, '공동인증서로도 로그인할 수 있나요?', '금융/간편 인증을 통한 로그인을 지원하며, 공동인증서는 일부 절차에서 사용될 수 있습니다.', 'SYSTEM', 'Y', now() - (59 || ' days')::interval, now() - (59 || ' days')::interval, 18),
(60, '고향사랑기부제란 무엇인가요?', '개인이 자신의 주소지 외 지자체에 기부하면 세액공제와 답례품을 받을 수 있는 제도입니다.', 'ETC', 'Y', now() - (60 || ' days')::interval, now() - (60 || ' days')::interval, 25),
(61, '문의는 어디로 하나요?', '고객센터 > 1:1문의 또는 대표전화 1522-2431로 문의하실 수 있습니다.', 'ETC', 'Y', now() - (61 || ' days')::interval, now() - (61 || ' days')::interval, 32),
(62, '고향사랑e음 운영시간은 어떻게 되나요?', '온라인 서비스는 24시간 이용 가능하나 기부 결제는 01:00~23:30만 가능합니다.', 'ETC', 'Y', now() - (62 || ' days')::interval, now() - (62 || ' days')::interval, 39)
ON CONFLICT (ID) DO NOTHING;

