-- =====================================================================
-- AS-IS VIEW 이관 (db-dump/VIEW). CUBRID 문법(대괄호 식별자, _utf8'...' COLLATE
-- utf8_bin, group_concat)을 Postgres로 변환. 셋 다 단일 서비스(admin) 테이블만
-- 참조해 그대로 이식 가능.
-- =====================================================================
CREATE OR REPLACE VIEW view_search_faq AS
SELECT id,
       title,
       CAST(content AS VARCHAR(255)) AS content,
       CAST('/faq/list.html' AS VARCHAR(14)) AS detail_url,
       created,
       faq_type
FROM op_faq
WHERE use_yn = 'Y';

CREATE OR REPLACE VIEW view_search_notice AS
SELECT notice_id,
       subject,
       created_date,
       CAST('/notice/list.html' AS VARCHAR(17)) AS detail_url,
       content,
       hits
FROM op_notice
WHERE locgov_code = '00000'
  AND use_yn = 'Y';

CREATE OR REPLACE VIEW view_search_databoard AS
SELECT a.subject,
       a.created_date,
       concat('/data-board/detail.html?dataId=', CAST(a.data_id AS VARCHAR)) AS detail_url,
       a.data_id,
       a.hits,
       (SELECT string_agg(f.file_ty, ',')
        FROM op_data_board_file f
        WHERE f.data_id = a.data_id) AS file_types,
       a.content
FROM op_data_board a
WHERE a.use_yn = 'Y';

