-- =====================================================================
-- 시스템 인프라: 접속IP허용목록 (AS-IS opmanager/access) - AS-IS had no auto-increment on
-- ALLOW_IP_ID; added for the new implementation (same pattern used throughout this project).
-- =====================================================================
CREATE SEQUENCE IF NOT EXISTS op_allow_ip_allow_ip_id_seq START WITH 1000;
ALTER TABLE OP_ALLOW_IP ALTER COLUMN ALLOW_IP_ID SET DEFAULT nextval('op_allow_ip_allow_ip_id_seq');
ALTER SEQUENCE op_allow_ip_allow_ip_id_seq OWNED BY OP_ALLOW_IP.ALLOW_IP_ID;

